.roadsidesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2e2418;
    background: linear-gradient(160deg, #f7f1e6 0%, #efe5d3 100%);
    border-radius: 18px;
}

.roadsidesim-container * {
    box-sizing: border-box;
}

.roadsidesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #4a3520 0%, #7a5a2e 55%, #b07a1e 100%);
    color: #fdf6e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(74, 53, 32, 0.32);
}

.roadsidesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.roadsidesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #f3dca6;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.roadsidesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f1e4cc;
}

.roadsidesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6a4f2b;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.roadsidesim-period-counter #currentDay,
.roadsidesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #4a3520;
}

.roadsidesim-round-name {
    background: #e6d3ab;
    color: #5a3f1a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.roadsidesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a2f17;
    background: #f6dcd2;
    padding: 4px 12px;
    border-radius: 999px;
}

.roadsidesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.roadsidesim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3d6bc;
    box-shadow: 0 4px 14px rgba(74, 53, 32, 0.07);
    border-top: 4px solid #b07a1e;
}

.roadsidesim-card-defense { border-top-color: #2f6f3e; }
.roadsidesim-card-contractor { border-top-color: #9a5b16; }
.roadsidesim-card-cash { border-top-color: #2f6fb0; }
.roadsidesim-card-capital { border-top-color: #8a6d3b; }

.roadsidesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7350;
}

.roadsidesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #4a3520;
}

.roadsidesim-card-defense .roadsidesim-value { color: #2f6f3e; }
.roadsidesim-card-contractor .roadsidesim-value { color: #9a5b16; }
.roadsidesim-card-cash .roadsidesim-value { color: #2f6fb0; }
.roadsidesim-card-capital .roadsidesim-value { color: #6a4f2b; }

.roadsidesim-sublabel {
    font-size: 0.76rem;
    color: #8a7350;
    line-height: 1.35;
}

.roadsidesim-contractor-fail .roadsidesim-value { color: #c0392b; }
.roadsidesim-contractor-target .roadsidesim-value { color: #2f6f3e; }

.roadsidesim-capital-over { border-top-color: #c0392b; }
.roadsidesim-capital-over .roadsidesim-value { color: #c0392b; }

.roadsidesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #4a3520;
    color: #fdf3df;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.roadsidesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.roadsidesim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #b07a1e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(74, 53, 32, 0.06);
}

.roadsidesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.roadsidesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #4a3520;
    margin-bottom: 6px;
}

.roadsidesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a3a26;
}

.roadsidesim-briefing-text strong { color: #2f6f3e; }
.roadsidesim-briefing-text em { color: #9a2f17; font-style: italic; }

.roadsidesim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3d6bc;
    box-shadow: 0 4px 14px rgba(74, 53, 32, 0.07);
}

.roadsidesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #4a3520;
    border-bottom: 2px solid #efe5d3;
    padding-bottom: 8px;
}

.roadsidesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #5a4528;
    margin: 14px 0 6px;
}

.roadsidesim-container select,
.roadsidesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d4c19a;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf6ec;
    color: #2e2418;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.roadsidesim-container select:focus,
.roadsidesim-container input[type="number"]:focus {
    outline: none;
    border-color: #b07a1e;
    box-shadow: 0 0 0 3px rgba(176, 122, 30, 0.18);
}

.roadsidesim-container select option {
    background-color: #fffdf8;
    color: #2e2418;
}

.roadsidesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b07a1e;
}

.roadsidesim-range-readout,
.roadsidesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #8a5b16;
    margin-top: 4px;
}

.roadsidesim-range-readout span:last-child,
.roadsidesim-alloc-readout span:nth-child(2) {
    color: #2f6f3e;
    font-weight: 800;
}

.roadsidesim-hint {
    font-size: 0.8rem;
    color: #8a7350;
    margin-top: 4px;
    line-height: 1.4;
}

.roadsidesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.roadsidesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6efe0;
    border: 1px solid #e3d6bc;
    border-radius: 9px;
    padding: 8px 12px;
}

.roadsidesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #5a4528;
}

.roadsidesim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.roadsidesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.roadsidesim-container .btn-primary {
    background: linear-gradient(135deg, #2f6f3e 0%, #b07a1e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 111, 62, 0.28);
}

.roadsidesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.roadsidesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d4c19a;
    color: #8a7350;
}

.roadsidesim-coach {
    background: #4a3520;
    color: #fdf3df;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(74, 53, 32, 0.24);
}

.roadsidesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6c073;
    margin-bottom: 8px;
}

.roadsidesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.roadsidesim-coach-body strong { color: #ffd98a; }
.roadsidesim-coach-body em { color: #ffb59c; font-style: italic; }

.roadsidesim-history,
.roadsidesim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3d6bc;
    box-shadow: 0 4px 14px rgba(74, 53, 32, 0.07);
}

.roadsidesim-history h3,
.roadsidesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #4a3520;
}

.roadsidesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3a26;
}

.roadsidesim-container table#usfHistoryTable th {
    background: #f2e7cf;
    color: #4a3520;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0cfa6;
}

.roadsidesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e8d6;
}

.roadsidesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf5e9;
}

.roadsidesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .roadsidesim-container {
        padding: 14px;
    }
    .roadsidesim-header h1 {
        font-size: 1.7rem;
    }
    .roadsidesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .roadsidesim-value {
        font-size: 2rem;
    }
    .roadsidesim-clock {
        margin-left: 0;
    }
    .roadsidesim-period-counter {
        font-size: 0.88rem;
    }
    .roadsidesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .roadsidesim-alloc-row {
        flex-wrap: wrap;
    }
    .roadsidesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .roadsidesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion debrief — self-contained, append-only. Roadside (hardware) palette. */
.roadsim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #2e2418; text-align: center; padding: 4px 2px 8px; }
.roadsim-cm-title { font-size: 20px; font-weight: 700; color: #4a3520; margin-bottom: 14px; }
.roadsim-cm-scorewrap { background: linear-gradient(135deg, #4a3520 0%, #7a5a2e 55%, #b07a1e 100%); color: #fffdf8; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.roadsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.roadsim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.roadsim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.roadsim-cm-badges { margin-top: 10px; }
.roadsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.roadsim-cm-badge-ok { background: #dcecd0; color: #2f6f3e; }
.roadsim-cm-badge-miss { background: #f6dcd2; color: #9a2f17; }
.roadsim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 500px; }
.roadsim-cm-kpi { flex: 1 1 105px; min-width: 105px; background: #fdf3df; border: 1px solid #e3d6bc; border-radius: 10px; padding: 10px 6px; }
.roadsim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #b07a1e; }
.roadsim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #6a4f2b; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.roadsim-cm-insights { text-align: left; max-width: 520px; margin: 0 auto; background: #fffdf8; border-left: 4px solid #b07a1e; border-radius: 8px; padding: 12px 16px; }
.roadsim-cm-ins-h { font-weight: 700; color: #4a3520; margin-bottom: 6px; font-size: 14px; }
.roadsim-cm-insights ul { margin: 0; padding-left: 18px; }
.roadsim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #3a2e1d; }
@media (max-width: 480px) { .roadsim-cm-kpi { flex-basis: 40%; } .roadsim-cm-score { font-size: 38px; } .roadsim-cm-scorewrap { max-width: 100%; } }

