(function() {
    'use strict';

    class RoadsideAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Roadside Strategy`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (concept §7), money in $k.
            this.CAPITAL_CAP = 300;          // hard cap, savings + 9.5% SBA line
            this.PRODESK_FULL = 140;         // contractor pro-desk + delivery (the right concentration)
            this.RENOVATE_FULL = 120;        // store renovation / broaden assortment
            this.SECONDSTORE_FULL = 420;     // second store (exceeds cap; partial $300k)
            this.SBA_RATE = 9.5;             // debt hurdle

            this.CONTRACTOR_TARGET = 85;     // contractor retention target %

            // Concept-correct answers (FACILITATOR DECISION TREE + COMMON ERRORS).
            this.RIGHT_SEGMENT = `contractor`;
            this.RIGHT_ADVANTAGE = `switching`;
            this.RIGHT_POSTURE = `targeted`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    // Starting KPIs (deliberately low headroom so a wrong path cannot peg the meters).
                    defense: 20,
                    contractor: 70,
                    cash: 55,
                    prodeskFunded: 0,
                    renovateFunded: 0,
                    secondstoreFunded: 0,
                    capitalCommitted: 0,
                    overCap: false,
                    priceWar: false,
                    wrongCustomer: false,
                    sprinkled: false,
                    overreach: false,
                    defenseHistory: [20],
                    contractorHistory: [70],
                    cashHistory: [55],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults mirror the HTML select first-options: the OWNER'S INSTINCT
                // (the classic Common Errors) — chase walk-ins, be cheapest, match prices,
                // sprinkle/lean into the second store, wait, grow size. A thoughtless
                // click-through therefore commits the WRONG path and must NOT auto-win;
                // the student has to actively choose the disciplined option in each select.
                state.decisions = {
                    segment: `retail`,
                    advantage: `price`,
                    clarity: 50,
                    posture: `blanket`,
                    value: `discount`,
                    image: 5,
                    discipline: 50,
                    prodesk: 60,
                    renovate: 60,
                    secondstore: 80,
                    attention: 50,
                    sequence: `wait`,
                    financing: `size`,
                    kpi: `revenue`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const seg = document.getElementById(`segmentInput`);
                const adv = document.getElementById(`advantageInput`);
                const cl = document.getElementById(`clarityInput`);
                if (seg) decisions.segment = seg.value;
                if (adv) decisions.advantage = adv.value;
                if (cl) decisions.clarity = parseInt(cl.value, 10);
                if (!Number.isFinite(decisions.clarity) || decisions.clarity < 0 || decisions.clarity > 100) {
                    warn(`warn_clarity_range`); return false;
                }
            } else if (round === 2) {
                const po = document.getElementById(`postureInput`);
                const va = document.getElementById(`valueInput`);
                const im = document.getElementById(`imageInput`);
                const di = document.getElementById(`disciplineInput`);
                if (po) decisions.posture = po.value;
                if (va) decisions.value = va.value;
                if (im) decisions.image = parseFloat(im.value);
                if (di) decisions.discipline = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.image) || decisions.image < 0 || decisions.image > 40) {
                    warn(`warn_image_range`); return false;
                }
                if (!Number.isFinite(decisions.discipline) || decisions.discipline < 0 || decisions.discipline > 100) {
                    warn(`warn_discipline_range`); return false;
                }
            } else if (round === 3) {
                const pd = document.getElementById(`prodeskInput`);
                const rn = document.getElementById(`renovateInput`);
                const ss = document.getElementById(`secondstoreInput`);
                const at = document.getElementById(`attentionInput`);
                if (pd) decisions.prodesk = parseFloat(pd.value);
                if (rn) decisions.renovate = parseFloat(rn.value);
                if (ss) decisions.secondstore = parseFloat(ss.value);
                if (at) decisions.attention = parseInt(at.value, 10);
                const allocs = [decisions.prodesk, decisions.renovate, decisions.secondstore];
                if (allocs.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                if (!Number.isFinite(decisions.attention) || decisions.attention < 0 || decisions.attention > 100) {
                    warn(`warn_attention_range`); return false;
                }
                const total = decisions.prodesk + decisions.renovate + decisions.secondstore;
                if (total <= 0) {
                    warn(`warn_alloc_zero`); return false;
                }
            } else if (round === 4) {
                const sq = document.getElementById(`sequenceInput`);
                const fi = document.getElementById(`financingInput`);
                const kp = document.getElementById(`kpiInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sq) decisions.sequence = sq.value;
                if (fi) decisions.financing = fi.value;
                if (kp) decisions.kpi = kp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let defenseDelta = 0, contractorDelta = 0, cashDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose where Granger truly has a defensible local advantage.
                // Compete where MegaBuild is WEAK — the contractor segment, not price-shoppers.
                if (d.segment === `contractor`) {
                    defenseDelta += 14; contractorDelta += 8; coachKey = `coach_r1_contractor`;
                } else if (d.segment === `ranch`) {
                    defenseDelta += 5; contractorDelta -= 4; coachKey = `coach_r1_ranch`;
                } else if (d.segment === `retail`) {
                    // Chasing weekend foot traffic — the segment MegaBuild wins easily.
                    defenseDelta -= 8; contractorDelta -= 12; cashDelta -= 4;
                    ds.wrongCustomer = true; coachKey = `coach_r1_retail`;
                } else { // everyone
                    defenseDelta -= 6; contractorDelta -= 6; coachKey = `coach_r1_everyone`;
                }

                // The real, durable advantage = service + switching costs, not low price.
                if (d.advantage === `switching`) {
                    defenseDelta += 14; contractorDelta += 6;
                    if (d.segment === `contractor`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.advantage === `selection`) {
                    defenseDelta -= 6; coachKey = `coach_r1_selection`;
                } else if (d.advantage === `price`) {
                    // Believing you can out-price a scale player is the core mistake.
                    defenseDelta -= 12; cashDelta -= 4; coachKey = `coach_r1_price`;
                } else { // none
                    defenseDelta -= 10; contractorDelta -= 4; coachKey = `coach_r1_none`;
                }

                // Clarity about what is truly at risk vs safe sharpens the whole plan.
                if (d.clarity >= 65) { defenseDelta += 7; }
                else if (d.clarity <= 30) { defenseDelta -= 6; coachKey = `coach_r1_lowclarity`; }

                summaryKey = (d.segment === `contractor` && d.advantage === `switching`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // The pricing decision. The 38% margin funds the service that IS the advantage.
                // A blanket 10% cut on commodity erases ~$130k of gross profit (concept §3).
                switch (d.posture) {
                    case `targeted`:
                        // Match ~10 known-value SKUs, hold price everywhere else.
                        defenseDelta += 8; contractorDelta += 6; cashDelta += 8; coachKey = `coach_r2_targeted`; break;
                    case `hold`:
                        defenseDelta += 2; cashDelta += 3; coachKey = `coach_r2_hold`; break;
                    case `blanket`:
                        // The unwinnable price war: bleed margin into a fight you cannot win.
                        defenseDelta -= 6; cashDelta -= 18; contractorDelta -= 2;
                        ds.priceWar = true; coachKey = `coach_r2_blanket`; break;
                    case `raise`:
                        // Raising price everywhere ignores price image and loses commodity volume.
                        defenseDelta -= 2; cashDelta -= 6; contractorDelta -= 4; coachKey = `coach_r2_raise`; break;
                }

                // On service-differentiated items, ADD VALUE rather than discount.
                switch (d.value) {
                    case `addvalue`:
                        defenseDelta += 8; cashDelta += 6; contractorDelta += 4; coachKey = (d.posture === `targeted`) ? `coach_r2_disciplined` : coachKey; break;
                    case `neutral`:
                        defenseDelta += 1; break;
                    case `discount`:
                        // Discounting your differentiated items too = throwing away pricing power.
                        defenseDelta -= 6; cashDelta -= 8; coachKey = `coach_r2_discount`; break;
                }

                // Price-image budget: a few loud known-value signals protect image cheaply.
                if (d.image >= 5 && d.image <= 20) { defenseDelta += 5; }
                else if (d.image > 20) { cashDelta -= 4; coachKey = `coach_r2_overimage`; }
                else { defenseDelta -= 3; coachKey = `coach_r2_noimage`; }

                // Margin discipline: refusal to chase MegaBuild down on commodity price.
                if (d.discipline >= 65) { cashDelta += 7; defenseDelta += 3; }
                else if (d.discipline <= 30) { cashDelta -= 8; ds.priceWar = true; coachKey = `coach_r2_lowdiscipline`; }

                summaryKey = (d.posture === `targeted` && d.value !== `discount` && d.discipline >= 50) ? `sum_r2_good` : (d.posture === `blanket` ? `sum_r2_war` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate $300k under a HARD cap. Concentration beats sprinkling.
                const pd = d.prodesk, rn = d.renovate, ss = d.secondstore;
                const total = pd + rn + ss;
                ds.prodeskFunded = pd;
                ds.renovateFunded = rn;
                ds.secondstoreFunded = ss;
                ds.capitalCommitted = total;

                // Over the cap draws the 9.5% SBA line — penalize over-borrowing.
                const over = total - this.CAPITAL_CAP;
                if (over > 0) {
                    ds.overCap = true;
                    cashDelta -= Math.min(22, 4 + over * 0.12);
                    coachKey = `coach_r3_overcap`;
                }

                // Pro-desk + delivery = the differentiation MegaBuild can't match well.
                // Reward FULL funding of the pro-desk (concentration on the right move).
                const prodeskFill = Math.min(1, pd / this.PRODESK_FULL);
                defenseDelta += Math.round(prodeskFill * 16);
                contractorDelta += Math.round(prodeskFill * 14);
                if (pd >= this.PRODESK_FULL) { cashDelta += 4; }

                // Renovation is a head-to-head selection fight — modest, not the winning move.
                const renovFill = Math.min(1, rn / this.RENOVATE_FULL);
                defenseDelta += Math.round(renovFill * 4);

                // Second store: expansion as reflex. Adds ~$180k/yr overhead, splits attention,
                // and partial funding ($300k of $420k) buys an unfinished, unaffordable store.
                if (ss >= 200) {
                    // Expansion-as-reflex: a heavy bet on the unaffordable second store.
                    defenseDelta -= 6; cashDelta -= 12; contractorDelta -= 6;
                    ds.overreach = true;
                    coachKey = `coach_r3_secondstore`;
                } else if (ss > 0 && ss < 100) {
                    // A down-payment on a store you can't finish = sprinkling into expansion.
                    cashDelta -= 3;
                }

                // Sprinkling: funding all three so nothing is a finished advantage.
                // A dominant second-store bet is OVERREACH, not sprinkling — don't double-flag it.
                const funded = [pd >= 40, rn >= 40, ss >= 40].filter(Boolean).length;
                const prodeskDominant = pd >= this.PRODESK_FULL && pd >= rn + ss;
                if (funded >= 3 && !prodeskDominant && !ds.overreach) {
                    ds.sprinkled = true;
                    defenseDelta -= 10; contractorDelta -= 6;
                    if (!ds.overCap) coachKey = `coach_r3_sprinkle`;
                } else if (prodeskDominant && (rn + ss) <= 120) {
                    // Concentration on the pro-desk, the rest small — the disciplined move.
                    defenseDelta += 4;
                    if (!ds.overCap) coachKey = `coach_r3_concentrate`;
                }

                // Owner-attention constraint: only fund what one owner can run well.
                if (d.attention >= 65) { defenseDelta += 5; cashDelta += 4; }
                else if (d.attention <= 30) { cashDelta -= 6; defenseDelta -= 4; coachKey = `coach_r3_attention`; }

                summaryKey = ds.overreach ? `sum_r3_overreach` : (ds.sprinkled ? `sum_r3_sprinkle` : (prodeskDominant && !ds.overCap ? `sum_r3_good` : `sum_r3_weak`));
            } else if (round === 4) {
                // Sequence the 9-month pre-entry plan and defend break-even / ROIC at 9.5%.
                switch (d.sequence) {
                    case `prodeskfirst`:
                        // Build contractor switching costs BEFORE MegaBuild opens.
                        defenseDelta += 10; contractorDelta += 12; coachKey = `coach_r4_prodeskfirst`; break;
                    case `even`:
                        defenseDelta += 1; contractorDelta += 1; coachKey = `coach_r4_even`; break;
                    case `wait`:
                        // Waiting hands MegaBuild the first move; switching costs are cheapest now.
                        defenseDelta -= 8; contractorDelta -= 10; cashDelta -= 4; coachKey = `coach_r4_wait`; break;
                }

                // Defend the financing to the SBA lender at 9.5%.
                switch (d.financing) {
                    case `hurdle`:
                        cashDelta += 12; defenseDelta += 4; coachKey = (d.sequence === `prodeskfirst`) ? `coach_r4_hurdle` : coachKey; break;
                    case `size`:
                        // "Bigger is safer" ignores break-even and ROIC.
                        cashDelta -= 8; coachKey = `coach_r4_size`; break;
                    case `ignore`:
                        // Not modelling break-even at all — the §6 fixed-cost trap.
                        cashDelta -= 14; coachKey = `coach_r4_ignore`; break;
                }

                // KPIs committed to founder and lender.
                switch (d.kpi) {
                    case `rightkpis`:
                        defenseDelta += 6; cashDelta += 6; contractorDelta += 4; break;
                    case `revenue`:
                        defenseDelta -= 2; coachKey = `coach_r4_revenue`; break;
                    case `none`:
                        defenseDelta -= 6; cashDelta -= 4; coachKey = `coach_r4_nokpi`; break;
                }

                // Conviction in competing where MegaBuild is weak over a price war.
                if (d.conviction >= 65) { defenseDelta += 4; }
                else if (d.conviction <= 30) { defenseDelta -= 4; }

                summaryKey = (d.sequence === `prodeskfirst` && d.financing === `hurdle` && d.kpi === `rightkpis`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with clamps; contractor retention is a % (keep headroom below 100).
            ds.defense = Math.max(0, Math.min(100, ds.defense + defenseDelta));
            ds.contractor = Math.max(0, Math.min(98, ds.contractor + contractorDelta));
            ds.cash = Math.max(0, Math.min(100, ds.cash + cashDelta));

            ds.defenseHistory.push(Math.round(ds.defense));
            ds.contractorHistory.push(Math.round(ds.contractor));
            ds.cashHistory.push(Math.round(ds.cash));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist the composite where the gradebook/score resolver reads it.
            // express_resolveDomainScore reads domainState.performance.overallScore first,
            // then a top-level score/netWorth; write both so the score never resolves to null.
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = { overallScore: _score };

            return {
                period: state.currentPeriod,
                defense: Math.round(ds.defense),
                defenseDelta: Math.round(defenseDelta),
                contractor: Math.round(ds.contractor),
                contractorDelta: Math.round(contractorDelta),
                cash: Math.round(ds.cash),
                cashDelta: Math.round(cashDelta),
                capitalCommitted: Math.round(ds.capitalCommitted),
                overCap: ds.overCap,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

