        // v1.1.0: single source of truth for the composite (verbatim v1.0.0 formula).
        _composite(ds) {
            const defense = Math.round(ds.defense);
            const contractor = Math.round(ds.contractor);
            const cash = Math.round(ds.cash);
            return Math.round(defense * 0.4 + contractor * 0.3 + cash * 0.3);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const defense = Math.round(ds.defense);
            const contractor = Math.round(ds.contractor);
            const cash = Math.round(ds.cash);

            const heldContractors = contractor >= this.CONTRACTOR_TARGET;
            const withinCap = !ds.overCap;
            const composite = this._composite(ds);

            // Any strategic error (price war, sprinkling, over-the-cap, expansion overreach,
            // or defending the wrong customer) DISQUALIFIES the top tiers regardless of how
            // high the composite climbs — a high score must not mask a Common Error.
            const cleanStrategy = !ds.priceWar && !ds.sprinkled && !ds.overCap && !ds.overreach && !ds.wrongCustomer;

            let performance = `Outflanked by MegaBuild`, performanceKey = `grade_outflanked`;
            if (composite >= 80 && heldContractors && cleanStrategy) { performance = `Defensible & Differentiated`; performanceKey = `grade_defensible`; }
            else if (composite >= 66 && heldContractors && cleanStrategy) { performance = `Repositioned in Time`; performanceKey = `grade_repositioned`; }
            else if (ds.priceWar) { performance = `Bled Out in a Price War`; performanceKey = `grade_pricewar`; }
            else if (ds.overCap) { performance = `Over-Leveraged on the SBA Line`; performanceKey = `grade_overcap`; }
            else if (ds.overreach) { performance = `Overreached on Expansion`; performanceKey = `grade_overreach`; }
            else if (ds.sprinkled) { performance = `Sprinkled — Nothing Finished`; performanceKey = `grade_sprinkled`; }
            else if (ds.wrongCustomer) { performance = `Defended the Wrong Customer`; performanceKey = `grade_wrongcustomer`; }
            else if (composite >= 52) { performance = `Improved but Exposed`; performanceKey = `grade_exposed`; }
            const met = heldContractors && cleanStrategy && composite >= 66;

            const insights = [];
            if (composite >= 80 && heldContractors && cleanStrategy) insights.push(window.mySimulation.t(`insight_great`));
            else if (heldContractors) insights.push(window.mySimulation.t(`insight_held`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (ds.priceWar) insights.push(window.mySimulation.t(`insight_pricewar`));
            if (ds.sprinkled) insights.push(window.mySimulation.t(`insight_sprinkle`));
            if (ds.overreach) insights.push(window.mySimulation.t(`insight_overreach`));
            if (ds.overCap) insights.push(window.mySimulation.t(`insight_overcap`));
            if (ds.wrongCustomer) insights.push(window.mySimulation.t(`insight_wrongcustomer`));
            if (defense >= 70 && cash >= 65) insights.push(window.mySimulation.t(`insight_roic`));

            return {
                defense: defense,
                contractor: contractor,
                cash: cash,
                heldContractors: heldContractors,
                withinCap: withinCap,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performance || ``);
            const badge = s.met
                ? `<span class="roadsim-cm-badge roadsim-cm-badge-ok">${t(`cm_targets_met`)}</span>`
                : `<span class="roadsim-cm-badge roadsim-cm-badge-miss">${t(`cm_targets_missed`)}</span>`;
            const kpi = (k, v, suf) => `<div class="roadsim-cm-kpi"><div class="roadsim-cm-kpi-val">${(v != null ? v : `—`)}${suf || ``}</div><div class="roadsim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="roadsim-cm-insights"><div class="roadsim-cm-ins-h">${t(`cm_insights`)}</div><ul>${ins.map((i) => `<li>${i}</li>`).join(``)}</ul></div>`
                : ``;
            return `
